const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// ── Palette ──────────────────────────────────────────────────────────────────
// Midnight Executive / deep-tech feel
const C = {
  navy:    "0B1E3A",  // dominant dark bg
  blue:    "1A3A6B",  // secondary bg blocks
  accent:  "00C2FF",  // vivid accent / highlight
  accentD: "0097CC",  // darker accent
  white:   "FFFFFF",
  offWhite:"EEF2F7",
  muted:   "8DA4BF",
  text:    "D6E4F0",
  textDark:"1A2E45",
  green:   "22C55E",  // positive / highlight
  orange:  "F59E0B",  // warning
  red:     "EF4444",  // critical
  lightBg: "F0F4FA",  // light slides bg
  cardBg:  "FFFFFF",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ── Font ──────────────────────────────────────────────────────────────────────
const TITLE_FONT  = "Calibri";
const BODY_FONT   = "Calibri";

// ── Helper: add a dark slide header bar ──────────────────────────────────────
function addHeader(slide, titleText, dark = false) {
  slide.addShape(slide._pptx ? slide._pptx.shapes.RECTANGLE : "rect", {
    x: 0, y: 0, w: 10, h: 0.78,
    fill: { color: dark ? C.navy : C.blue }, line: { color: dark ? C.navy : C.blue }
  });
  slide.addShape("rect", { x: 0, y: 0, w: 0.22, h: 0.78, fill: { color: C.accent }, line: { color: C.accent } });
  slide.addText(titleText, {
    x: 0.35, y: 0, w: 9.3, h: 0.78, margin: 0,
    fontFace: TITLE_FONT, fontSize: 20, bold: true,
    color: C.white, valign: "middle", align: "left"
  });
}

// ── Helper: add slide number ──────────────────────────────────────────────────
function addFooter(slide, num) {
  slide.addShape("rect", { x: 0, y: 5.425, w: 10, h: 0.2, fill: { color: C.navy }, line: { color: C.navy } });
  slide.addText(`${num} / 9`, {
    x: 8.8, y: 5.38, w: 1, h: 0.2, margin: 0,
    fontFace: BODY_FONT, fontSize: 9, color: C.muted, align: "right", valign: "middle"
  });
  slide.addText("VAPO · ByteDance Seed · AIME 2024", {
    x: 0.3, y: 5.38, w: 6, h: 0.2, margin: 0,
    fontFace: BODY_FONT, fontSize: 9, color: C.muted, align: "left", valign: "middle"
  });
}

// ── Helper: card box ─────────────────────────────────────────────────────────
function addCard(slide, x, y, w, h, opts = {}) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: opts.bg || C.cardBg },
    line: { color: opts.border || "D1DCF0", width: 1 },
    shadow: makeShadow()
  });
}

// ─────────────────────────────────────────────────────────────────────────────
async function build() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "VAPO Paper Summary";
  pres.title  = "VAPO: Value-Model-Based RL for Advanced Reasoning";

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 1 — Title
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.navy };

    // Accent bar left
    s.addShape("rect", { x: 0, y: 0, w: 0.45, h: 5.625, fill: { color: C.accent }, line: { color: C.accent } });

    // Top label
    s.addText("TECHNICAL PAPER SUMMARY", {
      x: 0.7, y: 0.45, w: 8, h: 0.3, margin: 0,
      fontFace: TITLE_FONT, fontSize: 11, bold: false,
      color: C.accent, charSpacing: 3, align: "left"
    });

    // Main title
    s.addText("VAPO", {
      x: 0.7, y: 0.9, w: 8.8, h: 1.1, margin: 0,
      fontFace: TITLE_FONT, fontSize: 72, bold: true,
      color: C.white, align: "left"
    });

    s.addText("Value-Model-Based RL for Advanced Reasoning", {
      x: 0.7, y: 2.0, w: 8.8, h: 0.6, margin: 0,
      fontFace: TITLE_FONT, fontSize: 22, bold: false,
      color: C.text, align: "left"
    });

    // Divider
    s.addShape("rect", { x: 0.7, y: 2.72, w: 5.5, h: 0.04, fill: { color: C.accentD }, line: { color: C.accentD } });

    // Key stat callout box
    s.addShape("rect", {
      x: 0.7, y: 2.92, w: 3.1, h: 1.65,
      fill: { color: C.blue }, line: { color: C.accent, width: 2 },
      shadow: makeShadow()
    });
    s.addText("60.4", {
      x: 0.7, y: 3.0, w: 3.1, h: 0.85, margin: 0,
      fontFace: TITLE_FONT, fontSize: 58, bold: true,
      color: C.accent, align: "center"
    });
    s.addText("AIME 2024 avg@32", {
      x: 0.7, y: 3.85, w: 3.1, h: 0.35, margin: 0,
      fontFace: BODY_FONT, fontSize: 12, color: C.text, align: "center"
    });
    s.addText("State-of-the-Art", {
      x: 0.7, y: 4.22, w: 3.1, h: 0.28, margin: 0,
      fontFace: BODY_FONT, fontSize: 10, bold: true, color: C.green, align: "center"
    });

    // Meta info
    s.addText([
      { text: "Base model: ", options: { color: C.muted, bold: false } },
      { text: "Qwen2.5-32B (no SFT)", options: { color: C.white, bold: true } },
      { text: "  ·  ", options: { color: C.muted } },
      { text: "Team: ", options: { color: C.muted } },
      { text: "ByteDance Seed", options: { color: C.white, bold: true } },
    ], {
      x: 4.05, y: 2.95, w: 5.5, h: 0.35, margin: 0,
      fontFace: BODY_FONT, fontSize: 12, align: "left", valign: "middle"
    });

    s.addText("+10+ pts vs DAPO  ·  No SFT data  ·  5,000 training steps", {
      x: 4.05, y: 3.4, w: 5.5, h: 0.3, margin: 0,
      fontFace: BODY_FONT, fontSize: 12, color: C.text, align: "left"
    });

    s.addText("arxiv.org/abs/2504.05118", {
      x: 4.05, y: 3.85, w: 5.5, h: 0.3, margin: 0,
      fontFace: BODY_FONT, fontSize: 11, italic: true, color: C.muted, align: "left"
    });

    addFooter(s, 1);
  }

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 2 — Motivation: Why Value Models?
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };
    addHeader(s, "Why Value Models? Finer Credit Assignment for Long Chain-of-Thought Reasoning", true);

    // Two-column layout: Value-Free (left) vs Value-Based (right)
    const cols = [
      { x: 0.28, label: "Value-Model-FREE", color: C.orange, methods: "GRPO · DAPO", items: [
        "Trajectory-level reward assigned uniformly to all tokens",
        "No distinction between good and bad intermediate steps",
        "Credit assignment is coarse — token-level errors go undetected",
        "Simpler to train, but limited for complex multi-step reasoning",
      ]},
      { x: 5.18, label: "Value-Model-BASED", color: C.green, methods: "VAPO (PPO family)", items: [
        "Precise token-level credit assignment via learned value function",
        "Traces each action's impact on final return",
        "Critical when subtle step-level errors cause catastrophic failures",
        "Lower-variance estimates per token vs Monte Carlo methods",
      ]},
    ];

    cols.forEach(col => {
      addCard(s, col.x, 0.95, 4.5, 4.25, { bg: C.cardBg });
      // Header band
      s.addShape("rect", {
        x: col.x, y: 0.95, w: 4.5, h: 0.55,
        fill: { color: col.color }, line: { color: col.color }
      });
      s.addText(col.label, {
        x: col.x + 0.15, y: 0.95, w: 4.2, h: 0.55, margin: 0,
        fontFace: TITLE_FONT, fontSize: 14, bold: true, color: C.white, valign: "middle"
      });
      s.addText(col.methods, {
        x: col.x + 0.15, y: 1.53, w: 4.2, h: 0.28, margin: 0,
        fontFace: BODY_FONT, fontSize: 10, italic: true, color: C.muted
      });
      col.items.forEach((item, i) => {
        s.addText([{ text: item, options: { bullet: true } }], {
          x: col.x + 0.18, y: 1.85 + i * 0.62, w: 4.1, h: 0.58,
          fontFace: BODY_FONT, fontSize: 12, color: C.textDark
        });
      });
    });

    // VS divider
    s.addShape("rect", { x: 4.86, y: 1.3, w: 0.28, h: 3.6, fill: { color: C.offWhite }, line: { color: C.offWhite } });
    s.addText("VS", {
      x: 4.86, y: 2.8, w: 0.28, h: 0.4, margin: 0,
      fontFace: TITLE_FONT, fontSize: 13, bold: true, color: C.muted, align: "center"
    });

    addFooter(s, 2);
  }

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 3 — Three Core Challenges
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };
    addHeader(s, "Three Challenges Plaguing Value-Model-Based RL in Long-CoT Tasks", true);

    const challenges = [
      {
        num: "01",
        title: "Value Model Bias",
        sub: "Long trajectories + bootstrapped learning",
        body: "In long-CoT tasks, value estimates must propagate through hundreds of tokens. Bootstrapped TD learning compounds errors, introducing systematic bias that distorts credit assignment."
      },
      {
        num: "02",
        title: "Heterogeneous Sequence Lengths",
        sub: "Different bias-variance tradeoffs needed",
        body: "Responses vary dramatically in length. A single fixed λ in GAE cannot simultaneously minimize variance for short outputs and bias for long outputs — the optimizer must trade one off against the other."
      },
      {
        num: "03",
        title: "Reward Signal Sparsity",
        sub: "Only the final <eos> token receives reward",
        body: "Binary final-answer rewards are assigned at a single terminal step. Over a 6,000-token trajectory, this sparse signal must propagate backwards through every reasoning step, severely degrading the learning signal."
      },
    ];

    challenges.forEach((c, i) => {
      const x = 0.28 + i * 3.18;
      addCard(s, x, 0.95, 2.98, 4.3, { bg: C.cardBg });
      // Number tag
      s.addShape("rect", { x, y: 0.95, w: 2.98, h: 0.7, fill: { color: C.navy }, line: { color: C.navy } });
      s.addText(c.num, {
        x: x + 0.12, y: 0.95, w: 0.7, h: 0.7, margin: 0,
        fontFace: TITLE_FONT, fontSize: 28, bold: true, color: C.accent, valign: "middle"
      });
      s.addText(c.title, {
        x: x + 0.82, y: 0.95, w: 2.0, h: 0.7, margin: 0,
        fontFace: TITLE_FONT, fontSize: 13, bold: true, color: C.white, valign: "middle"
      });
      // Sub
