    });

    // Right panel: key stats + figure reference
    s.addShape("rect", { x: 6.05, y: 0.9, w: 3.65, h: 4.3, fill: { color: C.navy }, line: { color: C.navy } });

    const stats = [
      { val: "60", label: "VAPO Score", color: C.accent },
      { val: "+10", label: "vs DAPO (50)", color: C.green },
