      { name: "VAPO w/o Value-Pretraining",     score: 11, contrib: -49,   isBaseline: false, isFull: false, isVapo: false, critical: true  },
      { name: "VAPO w/o Decoupled-GAE",         score: 33, contrib: -27,   isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Length-adaptive GAE",   score: 45, contrib: -15,   isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Clip-Higher",           score: 46, contrib: -14,   isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Token-level Loss",      score: 53, contrib: -7,    isBaseline: false, isFull: false, isVapo: false, critical: false },
