    s.addShape("rect", { x: 0, y: 0, w: 10, h: 0.78, fill: { color: "050E1E" }, line: { color: "050E1E" } });
    s.addShape("rect", { x: 0, y: 0, w: 0.22, h: 0.78, fill: { color: C.accent }, line: { color: C.accent } });
    s.addText("Key Takeaways: Value-Model-Based RL Is Back — With the Right Engineering", {
      x: 0.35, y: 0, w: 9.3, h: 0.78, margin: 0,
      fontFace: TITLE_FONT, fontSize: 18, bold: true,
      color: C.white, valign: "middle", align: "left"
    });

    const takeaways = [
      {
        num: "1",
        head: "Value-model-based RL can surpass value-free methods",
        body: "VAPO (60.4) beats DAPO (50) and DeepSeek-R1-Zero-Qwen-32B (47) — all on the same base model with no SFT — proving that value-model-based RL with proper engineering can outperform simpler policy-gradient methods.",
        color: C.accent,
      },
      {
        num: "2",
        head: "Value-Pretraining is the single most critical component",
        body: "Removing it collapses performance from 60 → 11 (−49 pts). Value models must be initialized well before RL begins; cold-starting the value model is nearly equivalent to Vanilla PPO.",
        color: C.red,
      },
      {
        num: "3",
        head: "Length-Adaptive GAE unlocks heterogeneous-length CoT training",
        body: "This novel technique dynamically tunes the bias-variance tradeoff per response length, contributing +15 points. It addresses a problem unique to long-CoT settings that prior work ignored.",
        color: C.green,
      },
      {
        num: "4",
        head: "VAPO is training-efficient and crash-free",
        body: "Reaches SOTA in ~5,000 steps with zero crashes across multiple independent runs. Stability matters: VAPO's value-model architecture enables consistent, reproducible training.",
        color: C.accent,
      },
      {
        num: "5",
        head: "Implications for future reasoning model development",
        body: "The three core challenges (bias, heterogeneous lengths, reward sparsity) are solvable. VAPO's component-driven ablation provides a clear roadmap: tackle these challenges systematically to push reasoning frontier further.",
        color: "6B9FCC",
      },
    ];

    const colBreak = 3; // first 3 go left, last 2 go right
    takeaways.forEach((t, i) => {
      const col = i < colBreak ? 0 : 1;
      const row = i < colBreak ? i : i - colBreak;
      const x = col === 0 ? 0.28 : 5.18;
      const y = 0.92 + row * 1.52;
      const h = col === 1 && row === 1 ? 2.2 : 1.35;

      addCard(s, x, y, 4.5, h, { bg: "0D2545" });
      // Number circle
