      s.addText(t.num, {
        x: x + 0.15, y: y + 0.15, w: 0.42, h: 0.42, margin: 0,
        fontFace: TITLE_FONT, fontSize: 15, bold: true, color: C.navy, align: "center", valign: "middle"
      });
      // Heading
      s.addText(t.head, {
        x: x + 0.68, y: y + 0.12, w: 3.65, h: 0.45, margin: 0,
        fontFace: TITLE_FONT, fontSize: 12, bold: true, color: t.color, valign: "middle"
      });
      // Body
      s.addText(t.body, {
        x: x + 0.15, y: y + 0.6, w: 4.2, h: h - 0.65,
        fontFace: BODY_FONT, fontSize: 10.5, color: C.text
      });
    });

    addFooter(s, 9);
  }

  // ── Write file ─────────────────────────────────────────────────────────────
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("✅  Saved: /app/output/final_deck.pptx");
}

build().catch(err => { console.error(err); process.exit(1); });
