// Midnight Executive / deep-tech feel
const C = {
  navy:    "0B1E3A",  // dominant dark bg
  blue:    "1A3A6B",  // secondary bg blocks
  accent:  "00C2FF",  // vivid accent / highlight
  accentD: "0097CC",  // darker accent
  white:   "FFFFFF",
  offWhite:"EEF2F7",
  muted:   "8DA4BF",
  text:    "D6E4F0",
  textDark:"1A2E45",
