      });
      s.addText(p.tradeoff, {
        x: p.x + 2.5, y: 2.18, w: 1.8, h: 0.3, margin: 0,
        fontFace: BODY_FONT, fontSize: 9, color: C.muted, align: "center"
      });
      // Explanation
      s.addText(p.why, {
        x: p.x + 0.2, y: 2.6, w: 4.1, h: 1.8,
        fontFace: BODY_FONT, fontSize: 12, color: C.textDark
      });
    });

    // Center connector with bias-variance label
    s.addText("Bias–Variance\nTradeoff", {
      x: 4.6, y: 2.8, w: 0.8, h: 0.6, margin: 0,
      fontFace: BODY_FONT, fontSize: 8.5, bold: true, color: C.navy, align: "center"
    });

    // Key insight callout at bottom
    s.addShape("rect", { x: 0.28, y: 5.02, w: 9.44, h: 0.4, fill: { color: C.navy }, line: { color: C.navy } });
    s.addText("Key Insight: Length-adaptive GAE is the only technique specifically designed for heterogeneous-length CoT responses, contributing +15 points to VAPO's final score.", {
      x: 0.45, y: 5.02, w: 9.1, h: 0.4, margin: 0,
      fontFace: BODY_FONT, fontSize: 11, color: C.accent, valign: "middle"
    });

    addFooter(s, 5);
  }

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 6 — Main Results (bar chart + training curve ref)
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };
    addHeader(s, "VAPO Scores 60 on AIME 2024 — 10+ Points Above DAPO and DeepSeek-R1-Zero", true);

    // Bar chart (left)
    s.addChart(pres.charts.BAR, [
      {
        name: "AIME 2024 avg@32",
        labels: ["Vanilla PPO", "DeepSeek-R1-Zero\nQwen-32B", "DAPO", "VAPO"],
        values: [5, 47, 50, 60]
      }
    ], {
      x: 0.28, y: 0.9, w: 5.5, h: 4.3,
      barDir: "col",
      barGapWidthPct: 55,
      chartColors: ["5B7FA6", "5B7FA6", "F59E0B", "00C2FF"],
      chartArea: { fill: { color: "FFFFFF" }, roundedCorners: false },
      plotArea: { fill: { color: "FFFFFF" } },
      catAxisLabelColor: "334155",
      valAxisLabelColor: "64748B",
      valGridLine: { color: "E2E8F0", size: 0.75 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: "0B1E3A",
      dataLabelFontSize: 13,
      dataLabelFontBold: true,
      showLegend: false,
      valAxisMinVal: 0,
      valAxisMaxVal: 70,
      catAxisLabelFontSize: 10,
    });

    // Y-axis label
    s.addText("AIME 2024 Score (avg@32)", {
      x: 0.05, y: 1.6, w: 1, h: 3.0, margin: 0,
      fontFace: BODY_FONT, fontSize: 10, color: C.muted, rotate: 270, align: "center"
    });

    // Right panel: key stats + figure reference
    s.addShape("rect", { x: 6.05, y: 0.9, w: 3.65, h: 4.3, fill: { color: C.navy }, line: { color: C.navy } });

    const stats = [
      { val: "60", label: "VAPO Score", color: C.accent },
      { val: "+10", label: "vs DAPO (50)", color: C.green },
      { val: "+13", label: "vs DeepSeek-R1-Zero (47)", color: C.green },
      { val: "5,000", label: "Training steps to SOTA", color: C.text },
    ];

    stats.forEach((st, i) => {
      s.addText(st.val, {
        x: 6.15, y: 1.05 + i * 0.98, w: 1.3, h: 0.6, margin: 0,
        fontFace: TITLE_FONT, fontSize: 32, bold: true, color: st.color, align: "center", valign: "bottom"
      });
      s.addText(st.label, {
        x: 6.15, y: 1.65 + i * 0.98, w: 1.3, h: 0.28, margin: 0,
        fontFace: BODY_FONT, fontSize: 9, color: C.muted, align: "center"
      });
      if (i < stats.length - 1) {
        s.addShape("rect", { x: 7.55, y: 1.05 + i * 0.98, w: 0.03, h: 0.88, fill: { color: "1A3A6B" }, line: { color: "1A3A6B" } });
      }
    });

    // Training curve figure reference
    s.addShape("rect", { x: 6.05, y: 4.82, w: 3.65, h: 0.38, fill: { color: "0D2545" }, line: { color: C.accentD } });
    s.addText("Fig 2: Training curves →  Slide 7", {
      x: 6.15, y: 4.82, w: 3.45, h: 0.38, margin: 0,
      fontFace: BODY_FONT, fontSize: 10, italic: true, color: C.muted, valign: "middle"
    });

    addFooter(s, 6);
  }

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 7 — Training Efficiency Curves
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.navy };
    addHeader(s, "VAPO Reaches SOTA in ~5K Steps — Stable Training, Longer Reasoning Chains");

    // Left: figure_2.jpg
    s.addShape("rect", { x: 0.28, y: 0.92, w: 5.7, h: 3.6, fill: { color: C.blue }, line: { color: C.accentD, width: 1 } });
    s.addImage({
      path: "/app/benchmark/assets/figure_2.jpg",
      x: 0.28, y: 0.92, w: 5.7, h: 3.6,
      sizing: { type: "contain", w: 5.7, h: 3.6 }
    });
    s.addText("Figure 2 · AIME 2024 Accuracy vs Training Steps", {
      x: 0.28, y: 4.55, w: 5.7, h: 0.28, margin: 0,
      fontFace: BODY_FONT, fontSize: 10, italic: true, color: C.muted, align: "center"
    });

    // Right: figure_3.jpg
    s.addShape("rect", { x: 6.22, y: 0.92, w: 3.5, h: 3.6, fill: { color: C.blue }, line: { color: C.accentD, width: 1 } });
    s.addImage({
      path: "/app/benchmark/assets/figure_3.jpg",
      x: 6.22, y: 0.92, w: 3.5, h: 3.6,
      sizing: { type: "contain", w: 3.5, h: 3.6 }
    });
    s.addText("Figure 3 · Mean Response Length (tokens) vs Steps", {
      x: 6.22, y: 4.55, w: 3.5, h: 0.28, margin: 0,
      fontFace: BODY_FONT, fontSize: 10, italic: true, color: C.muted, align: "center"
    });

    // Key callouts
    const callouts = [
      { text: "VAPO hits 60% accuracy at step ~4,500 vs DAPO's ~5,500 for only 50%", x: 0.28 },
      { text: "Zero training crashes across multiple independent runs — DAPO is less stable", x: 5.05 },
    ];
    callouts.forEach((c, i) => {
      s.addShape("rect", { x: c.x, y: 4.88, w: 4.65, h: 0.52, fill: { color: "0D2545" }, line: { color: C.accentD, width: 1 } });
      s.addShape("rect", { x: c.x, y: 4.88, w: 0.1, h: 0.52, fill: { color: C.accent }, line: { color: C.accent } });
      s.addText(c.text, {
        x: c.x + 0.2, y: 4.88, w: 4.35, h: 0.52, margin: 0,
        fontFace: BODY_FONT, fontSize: 11, color: C.text, valign: "middle"
      });
    });

    addFooter(s, 7);
  }

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 8 — Ablation Study
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };
    addHeader(s, "Ablation: Every Component Matters — Value-Pretraining Alone Adds 49 Points", true);

    // Ablation table data
    const rows = [
      { name: "Vanilla PPO",                   score: 5,  contrib: null,  isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Value-Pretraining",     score: 11, contrib: -49,   isBaseline: false, isFull: false, isVapo: false, critical: true  },
      { name: "VAPO w/o Decoupled-GAE",         score: 33, contrib: -27,   isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Length-adaptive GAE",   score: 45, contrib: -15,   isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Clip-Higher",           score: 46, contrib: -14,   isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Token-level Loss",      score: 53, contrib: -7,    isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Positive Example Loss", score: 54, contrib: -6,    isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO w/o Group-Sampling",        score: 55, contrib: -5,    isBaseline: false, isFull: false, isVapo: false, critical: false },
      { name: "VAPO (Full)",                    score: 60, contrib: null,   isBaseline: false, isFull: false, isVapo: true,  critical: false },
    ];

    // Table
    const TABLE_X = 0.28;
    const TABLE_Y = 0.92;
    const TABLE_W = 6.1;
    const ROW_H = 0.44;

    // Header row
    s.addShape("rect", { x: TABLE_X, y: TABLE_Y, w: TABLE_W, h: ROW_H, fill: { color: C.navy }, line: { color: C.navy } });
    s.addText("Model / Ablation",            { x: TABLE_X + 0.1, y: TABLE_Y, w: 3.5, h: ROW_H, margin: 0, fontFace: TITLE_FONT, fontSize: 11, bold: true, color: C.white, valign: "middle" });
    s.addText("AIME24", { x: TABLE_X + 3.65, y: TABLE_Y, w: 1.1, h: ROW_H, margin: 0, fontFace: TITLE_FONT, fontSize: 11, bold: true, color: C.white, align: "center", valign: "middle" });
    s.addText("Drop",   { x: TABLE_X + 4.8,  y: TABLE_Y, w: 1.2, h: ROW_H, margin: 0, fontFace: TITLE_FONT, fontSize: 11, bold: true, color: C.white, align: "center", valign: "middle" });

    rows.forEach((row, i) => {
      const y = TABLE_Y + ROW_H + i * ROW_H;
      const bg = row.isVapo ? C.navy : row.critical ? "FFF0F0" : i % 2 === 0 ? C.cardBg : C.offWhite;
      const textColor = row.isVapo ? C.accent : row.critical ? C.red : C.textDark;

      s.addShape("rect", { x: TABLE_X, y, w: TABLE_W, h: ROW_H, fill: { color: bg }, line: { color: "D1DCF0", width: 1 } });

      if (row.critical) {
        s.addShape("rect", { x: TABLE_X, y, w: 0.1, h: ROW_H, fill: { color: C.red }, line: { color: C.red } });
      } else if (row.isVapo) {
        s.addShape("rect", { x: TABLE_X, y, w: 0.1, h: ROW_H, fill: { color: C.accent }, line: { color: C.accent } });
      }

      s.addText(row.name, {
        x: TABLE_X + 0.18, y, w: 3.5, h: ROW_H, margin: 0,
        fontFace: BODY_FONT, fontSize: 11, bold: row.isVapo, color: textColor, valign: "middle"
      });
      s.addText(String(row.score), {
        x: TABLE_X + 3.65, y, w: 1.1, h: ROW_H, margin: 0,
        fontFace: TITLE_FONT, fontSize: 13, bold: row.isVapo, color: row.isVapo ? C.accent : textColor, align: "center", valign: "middle"
      });
      const contribStr = row.contrib !== null ? `−${Math.abs(row.contrib)}` : "—";
      s.addText(contribStr, {
        x: TABLE_X + 4.8, y, w: 1.2, h: ROW_H, margin: 0,
        fontFace: TITLE_FONT, fontSize: 13, bold: row.critical, color: row.contrib !== null ? C.red : C.muted, align: "center", valign: "middle"
      });
    });

    // Bar chart of ablation (right side)
    s.addChart(pres.charts.BAR, [
      {
        name: "AIME24 Score",
        labels: ["Vanilla PPO", "−Value\nPretraining", "−Decoupled\nGAE", "−Length\nAdaptive GAE", "−Clip\nHigher", "−Token\nLoss", "−Pos Example\nLoss", "−Group\nSampling", "VAPO\n(Full)"],
        values: [5, 11, 33, 45, 46, 53, 54, 55, 60]
      }
    ], {
      x: 6.5, y: 0.9, w: 3.2, h: 4.75,
      barDir: "bar",
      barGapWidthPct: 35,
      chartColors: ["94A3B8", "EF4444", "F59E0B", "F59E0B", "F59E0B", "F59E0B", "F59E0B", "F59E0B", "00C2FF"],
      chartArea: { fill: { color: "FFFFFF" }, roundedCorners: false },
      plotArea: { fill: { color: "FFFFFF" } },
      catAxisLabelColor: "334155",
      valAxisLabelColor: "64748B",
      catAxisLabelFontSize: 8,
      valGridLine: { color: "E2E8F0", size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: "0B1E3A",
      dataLabelFontSize: 9,
      showLegend: false,
      valAxisMinVal: 0,
      valAxisMaxVal: 65,
    });

    // Critical callout
    s.addShape("rect", { x: TABLE_X, y: 5.06, w: TABLE_W, h: 0.36, fill: { color: "FFF0F0" }, line: { color: C.red, width: 1 } });
    s.addShape("rect", { x: TABLE_X, y: 5.06, w: 0.1, h: 0.36, fill: { color: C.red }, line: { color: C.red } });
    s.addText("⚠  Removing Value-Pretraining is catastrophic: score crashes from 60 → 11 (−49 pts). Value pretraining is the single most critical component.", {
      x: TABLE_X + 0.2, y: 5.06, w: TABLE_W - 0.3, h: 0.36, margin: 0,
      fontFace: BODY_FONT, fontSize: 10, color: C.red, valign: "middle"
    });

    addFooter(s, 8);
  }

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 9 — Key Takeaways
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.navy };

    // Full dark header
    s.addShape("rect", { x: 0, y: 0, w: 10, h: 0.78, fill: { color: "050E1E" }, line: { color: "050E1E" } });
    s.addShape("rect", { x: 0, y: 0, w: 0.22, h: 0.78, fill: { color: C.accent }, line: { color: C.accent } });
    s.addText("Key Takeaways: Value-Model-Based RL Is Back — With the Right Engineering", {
      x: 0.35, y: 0, w: 9.3, h: 0.78, margin: 0,
      fontFace: TITLE_FONT, fontSize: 18, bold: true,
      color: C.white, valign: "middle", align: "left"
    });

    const takeaways = [
      {
        num: "1",
        head: "Value-model-based RL can surpass value-free methods",
        body: "VAPO (60.4) beats DAPO (50) and DeepSeek-R1-Zero-Qwen-32B (47) — all on the same base model with no SFT — proving that value-model-based RL with proper engineering can outperform simpler policy-gradient methods.",
        color: C.accent,
      },
      {
        num: "2",
        head: "Value-Pretraining is the single most critical component",
        body: "Removing it collapses performance from 60 → 11 (−49 pts). Value models must be initialized well before RL begins; cold-starting the value model is nearly equivalent to Vanilla PPO.",
        color: C.red,
      },
      {
        num: "3",
        head: "Length-Adaptive GAE unlocks heterogeneous-length CoT training",
        body: "This novel technique dynamically tunes the bias-variance tradeoff per response length, contributing +15 points. It addresses a problem unique to long-CoT settings that prior work ignored.",
        color: C.green,
      },
      {
        num: "4",
        head: "VAPO is training-efficient and crash-free",
        body: "Reaches SOTA in ~5,000 steps with zero crashes across multiple independent runs. Stability matters: VAPO's value-model architecture enables consistent, reproducible training.",
        color: C.accent,
      },
      {
        num: "5",
        head: "Implications for future reasoning model development",
        body: "The three core challenges (bias, heterogeneous lengths, reward sparsity) are solvable. VAPO's component-driven ablation provides a clear roadmap: tackle these challenges systematically to push reasoning frontier further.",
        color: "6B9FCC",
      },
    ];

    const colBreak = 3; // first 3 go left, last 2 go right
    takeaways.forEach((t, i) => {
      const col = i < colBreak ? 0 : 1;
      const row = i < colBreak ? i : i - colBreak;
      const x = col === 0 ? 0.28 : 5.18;
      const y = 0.92 + row * 1.52;
      const h = col === 1 && row === 1 ? 2.2 : 1.35;

      addCard(s, x, y, 4.5, h, { bg: "0D2545" });
      // Number circle
      s.addShape("oval", { x: x + 0.15, y: y + 0.15, w: 0.42, h: 0.42, fill: { color: t.color }, line: { color: t.color } });
      s.addText(t.num, {
        x: x + 0.15, y: y + 0.15, w: 0.42, h: 0.42, margin: 0,
        fontFace: TITLE_FONT, fontSize: 15, bold: true, color: C.navy, align: "center", valign: "middle"
      });
      // Heading
      s.addText(t.head, {
        x: x + 0.68, y: y + 0.12, w: 3.65, h: 0.45, margin: 0,
        fontFace: TITLE_FONT, fontSize: 12, bold: true, color: t.color, valign: "middle"
      });
      // Body
      s.addText(t.body, {
        x: x + 0.15, y: y + 0.6, w: 4.2, h: h - 0.65,
        fontFace: BODY_FONT, fontSize: 10.5, color: C.text
      });
    });

    addFooter(s, 9);
  }

  // ── Write file ─────────────────────────────────────────────────────────────
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("✅  Saved: /app/output/final_deck.pptx");
}

build().catch(err => { console.error(err); process.exit(1); });

