const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// ── Palette ──────────────────────────────────────────────────────────────────
// Midnight Executive / deep-tech feel
const C = {
  navy:    "0B1E3A",  // dominant dark bg
  blue:    "1A3A6B",  // secondary bg blocks
  accent:  "00C2FF",  // vivid accent / highlight
  accentD: "0097CC",  // darker accent
  white:   "FFFFFF",
  offWhite:"EEF2F7",
  muted:   "8DA4BF",
  text:    "D6E4F0",
  textDark:"1A2E45",
  green:   "22C55E",  // positive / highlight
  orange:  "F59E0B",  // warning
  red:     "EF4444",  // critical
  lightBg: "F0F4FA",  // light slides bg
  cardBg:  "FFFFFF",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ── Font ──────────────────────────────────────────────────────────────────────
const TITLE_FONT  = "Calibri";
const BODY_FONT   = "Calibri";

// ── Helper: add a dark slide header bar ──────────────────────────────────────
function addHeader(slide, titleText, dark = false) {
  slide.addShape(slide._pptx ? slide._pptx.shapes.RECTANGLE : "rect", {
    x: 0, y: 0, w: 10, h: 0.78,
    fill: { color: dark ? C.navy : C.blue }, line: { color: dark ? C.navy : C.blue }
  });
  slide.addShape("rect", { x: 0, y: 0, w: 0.22, h: 0.78, fill: { color: C.accent }, line: { color: C.accent } });
  slide.addText(titleText, {
    x: 0.35, y: 0, w: 9.3, h: 0.78, margin: 0,
    fontFace: TITLE_FONT, fontSize: 20, bold: true,
    color: C.white, valign: "middle", align: "left"
  });
}

// ── Helper: add slide number ──────────────────────────────────────────────────
function addFooter(slide, num) {
  slide.addShape("rect", { x: 0, y: 5.425, w: 10, h: 0.2, fill: { color: C.navy }, line: { color: C.navy } });
  slide.addText(`${num} / 9`, {
    x: 8.8, y: 5.38, w: 1, h: 0.2, margin: 0,
    fontFace: BODY_FONT, fontSize: 9, color: C.muted, align: "right", valign: "middle"
  });
  slide.addText("VAPO · ByteDance Seed · AIME 2024", {
    x: 0.3, y: 5.38, w: 6, h: 0.2, margin: 0,
    fontFace: BODY_FONT, fontSize: 9, color: C.muted, align: "left", valign: "middle"
  });
}

// ── Helper: card box ─────────────────────────────────────────────────────────
function addCard(slide, x, y, w, h, opts = {}) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: opts.bg || C.cardBg },
    line: { color: opts.border || "D1DCF0", width: 1 },
    shadow: makeShadow()
  });
}

// ─────────────────────────────────────────────────────────────────────────────
async function build() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "VAPO Paper Summary";
  pres.title  = "VAPO: Value-Model-Based RL for Advanced Reasoning";

  // ══════════════════════════════════════════════════════════════════════════
  // SLIDE 1 — Title
  // ══════════════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.navy };

    // Accent bar left
    s.addShape("rect", { x: 0, y: 0, w: 0.45, h: 5.625, fill: { color: C.accent }, line: { color: C.accent } });

    // Top label
    s.addText("TECHNICAL PAPER SUMMARY", {
      x: 0.7, y: 0.45, w: 8, h: 0.3, margin: 0,
      fontFace: TITLE_FONT, fontSize: 11, bold: false,
      color: C.accent, charSpacing: 3, align: "left"
    });

    // Main title
    s.addText("VAPO", {
      x: 0.7, y: 0.9, w: 8.8, h: 1.1, margin: 0,
      fontFace: TITLE_FONT, fontSize: 72, bold: true,
      color: C.white, align: "left"
    });

    s.addText("Value-Model-Based RL for Advanced Reasoning", {
      x: 0.7, y: 2.0, w: 8.8, h: 0.6, margin: 0,
      fontFace: TITLE_FONT, fontSize: 22, bold: false,
      color: C.text, align: "left"
    });

    // Divider
    s.addShape("rect", { x: 0.7, y: 2.72, w: 5.5, h: 0.04, fill: { color: C.accentD }, line: { color: C.accentD } });

    // Key stat callout box
    s.addShape("rect", {
      x: 0.7, y: 2.92, w: 3.1, h: 1.65,
      fill: { color: C.blue }, line: { color: C.accent, width: 2 },
      shadow: makeShadow()
    });
    s.addText("60.4", {
      x: 0.7, y: 3.0, w: 3.1, h: 0.85, margin: 0,
      fontFace: TITLE_FONT, fontSize: 58, bold: true,
      color: C.accent, align: "center"
    });
    s.addText("AIME 2024 avg@32", {
      x: 0.7, y: 3.85, w: 3.1, h: 0.35, margin: 0,
