{
  const s = pres.addSlide();
  s.background = { color: C.navy };
  addHeader(s, "VAPO Framework: Integrated Solutions for Value-Model-Based Reasoning RL");

  // Challenge column headers
  const challenges = ["Challenge 1\nValue Model Bias", "Challenge 2\nHeterogeneous Lengths", "Challenge 3\nReward Sparsity"];
  const chCols = [0.5, 3.7, 6.9];
  const chW = 2.8;
  chCols.forEach((x, i) => {
    s.addShape("rect", { x, y: 0.9, w: chW, h: 0.6, fill: { color: C.blue }, line: { color: C.accentD, width: 1 } });
    s.addText(challenges[i], {
      x, y: 0.9, w: chW, h: 0.6, margin: 0,
      fontFace: TITLE_FONT, fontSize: 10.5, bold: true,
      color: C.accent, align: "center", valign: "middle"
    });
  });

  // Component rows
  const components = [
    { name: "Value-Pretraining",        origin: "Novel (VAPO)",  challenge: 0, desc: "Pre-trains value model before RL to reduce initial bias",           color: C.accent },
    { name: "Decoupled-GAE",            origin: "from VC-PPO",   challenge: 0, desc: "Separates GAE computation for robust value estimation",             color: C.accentD },
    { name: "Length-Adaptive GAE",      origin: "Novel (VAPO)",  challenge: 1, desc: "Dynamic λ per response length — low λ for short, high λ for long",  color: C.accent },
    { name: "Clip-Higher",              origin: "from DAPO",     challenge: 2, desc: "Asymmetric clipping to encourage exploration",                       color: "6B9FCC" },
    { name: "Token-level Loss",         origin: "from DAPO",     challenge: 2, desc: "Normalizes loss at token level rather than sequence level",          color: "6B9FCC" },
    { name: "Positive Example LM Loss", origin: "from GRPO",     challenge: 2, desc: "Self-imitation learning on correct trajectories",                    color: "6B9FCC" },
    { name: "Group-Sampling",           origin: "from GRPO",     challenge: 2, desc: "Samples multiple responses per prompt for better baseline",          color: "6B9FCC" },
  ];

  // Draw connector arrows from challenge header to cards
  const arrowXMap = { 0: 1.9, 1: 5.1, 2: 8.3 };

  components.forEach((comp, i) => {
    const y = 1.68 + i * 0.55;
    // Full-width row bg
    s.addShape("rect", { x: 0.28, y: y, w: 9.44, h: 0.48, fill: { color: "0D2545" }, line: { color: "1A3A6B", width: 1 } });
    // Accent left bar matching challenge color
    s.addShape("rect", { x: 0.28, y: y, w: 0.1, h: 0.48, fill: { color: comp.color }, line: { color: comp.color } });

    // Component name
    s.addText(comp.name, {
      x: 0.5, y: y, w: 2.4, h: 0.48, margin: 0,
      fontFace: TITLE_FONT, fontSize: 12, bold: true, color: C.white, valign: "middle"
    });
    // Origin badge
    s.addShape("rect", { x: 2.98, y: y + 0.1, w: 1.1, h: 0.28, fill: { color: C.blue }, line: { color: C.accentD } });
    s.addText(comp.origin, {
      x: 2.98, y: y + 0.1, w: 1.1, h: 0.28, margin: 0,
      fontFace: BODY_FONT, fontSize: 8.5, italic: true, color: C.accent, align: "center", valign: "middle"
    });
    // Description
    s.addText(comp.desc, {
      x: 4.18, y: y, w: 5.5, h: 0.48, margin: 0,
      fontFace: BODY_FONT, fontSize: 11, color: C.text, valign: "middle"
    });

    // Challenge indicator dot
    const dotX = arrowXMap[comp.challenge];
    s.addShape("oval", {
      x: dotX - 0.12, y: y + 0.14, w: 0.2, h: 0.2,
      fill: { color: comp.color }, line: { color: comp.color }
    });
  });

  addFooter(s, 4);
}

