  {
    num: "1",
    head: "Value-model RL can surpass value-free methods",
    body: "VAPO (60.4) beats DAPO (50) and DeepSeek-R1-Zero (47) — all on the same Qwen2.5-32B base, no SFT — proving value-model-based RL can outperform policy-gradient methods when engineered properly.",
    color: C.accent,
  },
  {
    num: "2",
    head: "Value-Pretraining: the single most critical component",
    body: "Removing it collapses score from 60 to 11 (−49 pts). Cold-starting the value model is nearly equivalent to Vanilla PPO. Value models must be initialized well before RL begins.",
    color: C.red,
  },
  {
    num: "3",
    head: "Length-Adaptive GAE: novel +15 point contribution",
    body: "Dynamically tunes the bias-variance tradeoff per response length. Addresses a problem unique to long-CoT settings that prior work ignored — short responses use low λ, long responses use high λ.",
    color: C.green,
  },
  {
    num: "4",
    head: "Training-efficient and crash-free",
    body: "Reaches SOTA in ~5,000 steps with zero crashes across multiple independent runs, outpacing DAPO which needs ~5,500 steps for a lower score.",
    color: C.accent,
  },
  {
    num: "5",
    head: "A roadmap for future reasoning model development",
    body: "The three core challenges (bias, heterogeneous lengths, reward sparsity) are solvable. VAPO's ablation provides a clear engineering roadmap for pushing reasoning frontiers further.",
    color: "6B9FCC",
  },
];

// Layout: 3 cards top row, 2 cards bottom row centered
const CARD_W = 2.95;
const CARD_H = 2.05;
const TOP_Y = 0.88;
const BOT_Y = 3.05;
const positions = [
  { x: 0.28,  y: TOP_Y },
  { x: 3.51,  y: TOP_Y },
  { x: 6.74,  y: TOP_Y },
  { x: 1.89,  y: BOT_Y },
  { x: 5.12,  y: BOT_Y },
];

takeaways.forEach((t, i) => {
  const { x, y } = positions[i];
  addCard(s, x, y, CARD_W, CARD_H, { bg: "0D2545" });
  // Number circle
  s.addShape("oval", { x: x + 0.14, y: y + 0.14, w: 0.38, h: 0.38, fill: { color: t.color }, line: { color: t.color } });
  s.addText(t.num, {
    x: x + 0.14, y: y + 0.14, w: 0.38, h: 0.38, margin: 0,
    fontFace: TITLE_FONT, fontSize: 14, bold: true, color: C.navy, align: "center", valign: "middle"
  });
  // Heading
  s.addText(t.head, {
    x: x + 0.62, y: y + 0.1, w: CARD_W - 0.74, h: 0.5, margin: 0,
    fontFace: TITLE_FONT, fontSize: 11.5, bold: true, color: t.color, valign: "middle"
  });
  // Body
  s.addText(t.body, {
    x: x + 0.14, y: y + 0.65, w: CARD_W - 0.28, h: CARD_H - 0.75,
    fontFace: BODY_FONT, fontSize: 10, color: C.text
  });
});

